'use strict';
const fortune=EldoriaFortuneModel;
fortune.observe(state,atmosphere.conditions(state));fortune.roll(state,atmosphere.conditions(state));
const fortuneCSS=document.createElement('link');fortuneCSS.rel='stylesheet';fortuneCSS.href='city-fortune.css?v=1';document.head.append(fortuneCSS);
const fortuneButton=document.createElement('button');fortuneButton.id='fortuneBoard';fortuneButton.textContent='The midnight blessing';fortuneButton.onclick=fortuneBoard;document.querySelector('.city-life-bar').append(fortuneButton);
function fortuneBoard(){const f=fortune.ensure(state),c=atmosphere.conditions(state),working=c.hour<6;modal('The midnight magic lives on','<span class="city-eyebrow">THE ELVES AND THE SHOEMAKER · A LIVING PROMISE</span><p class="life-dialogue">The shoemaker laid out his leather at night. The elves made shoes so fine that his work brought prosperity. Their generosity remains alive in Eldoria: what you finish with care carries a little of their magic.</p><p><strong>Elven-finished creations:</strong> '+f.made+' · <strong>Fortune earned:</strong> '+f.earned+' mooncoins.</p><p>Completed shoemaking, baking, alchemy, gardening, home projects and heritage activities receive an extra <strong>5 mooncoins</strong> and the elven-finished quality blessing. Your ordinary rewards remain yours.</p><p><strong>The real midnight visit:</strong> from 12:00 a.m. until 6:00 a.m. in '+lifeEsc(state.cityAtmosphere.timeZone)+', the helpers work in the original shop. At dawn they leave a pair worth 12 mooncoins, plus 2 for each creation waiting for their overnight blessing. The gift waits here if you are away.</p><p class="fortune-status">'+(working?'The midnight helpers are at work. Their morning gift will be ready at 6:00 a.m.':'The shop waits for the helpers’ next midnight visit.')+'</p><p><strong>Morning fortune waiting:</strong> '+f.gift+' mooncoins.</p><h3>The fortune ledger</h3>'+(f.ledger.map(text=>'<p class="fortune-ledger">'+lifeEsc(text)+'</p>').join('')||'<p>Make something in Eldoria to begin your ledger. The magic honors completed work.</p>'));if(f.gift>0)action('Collect the helpers’ morning fortune',()=>{if(scene!=='workshop'||cityInside!=='originalShop'){heritageTravel('workshop','originalShop',fortuneBoard);return}const r=fortune.claim(state,lifeWhere());if(r.ok){persist();cityDraw();modal('The workbench holds a gift','<p>The shoes are beautifully finished. Their sale brings you '+r.coins+' mooncoins. The shop’s good fortune continues.</p>');action('Return to the magical shop',()=>{$('modal').close();cityDraw()})}});action('Visit the midnight workbench',heritageOriginal);action('Remember the first magical night',()=>heritageActivity('originaltale'));action('Return to Eldoria',()=>{$('modal').close();cityDraw()})}
function fortuneRender(){const f=fortune.ensure(state),c=atmosphere.conditions(state),night=c.hour<6,inside=cityInside==='originalShop';$('cityScene').classList.toggle('fortune-midnight',inside&&night);let status=$('fortuneShopStatus');if(!status){status=document.createElement('button');status.id='fortuneShopStatus';status.onclick=fortuneBoard;$('cityScene').append(status)}status.hidden=!inside;if(inside)status.textContent=night?'The midnight helpers are making their shoes…':f.gift?'The helpers left '+f.gift+' mooncoins of morning fortune':'The elves’ good fortune lives in this shop';if(inside&&night)$('hint').textContent='Silver stitches move across the workbench. The midnight helpers will leave their gift at dawn.';const result=$('cityResult');if(f.made>0&&result&&!result.textContent.includes('Elven-finished'))result.textContent+=' · Elven-finished creations carry good fortune.'}
const fortunePersistBefore=persist;persist=function(){const c=atmosphere.conditions(state);fortune.observe(state,c);fortune.roll(state,c);fortunePersistBefore()};
const fortuneDrawBefore=cityDraw;cityDraw=function(){fortuneDrawBefore();fortuneRender()};comfortDraw=cityDraw;
const fortuneActionsBefore=cityBuildActions;cityBuildActions=function(){fortuneActionsBefore();if(cityInside==='originalShop'){const f=fortune.ensure(state);const card=cityCard('The elves still come at midnight',f.gift?f.gift+' mooncoins of morning fortune are waiting on the workbench.':'Their beautiful work brought prosperity. Completed creations throughout Eldoria still carry their blessing.',f.gift?'View the morning gift':'Open the fortune ledger',fortuneBoard,'✦');$('comfortPlaces').prepend(card)}};
const fortuneModalBefore=modal;modal=function(title,body){fortuneModalBefore(title,body);const f=fortune.ensure(state);if(f.made>0&&/pair worth|draught glows|complete|little progress/i.test(title)){const p=document.createElement('p');p.className='fortune-quality';p.textContent='Elven-finished · Your completed work has brought an extra measure of fortune. See the midnight ledger for your bonuses.';$('modal').append(p)}};
window.ELDORIA_FORTUNE={version:1,openLedger:fortuneBoard};
cityDraw();persist();setInterval(()=>{const c=atmosphere.conditions(state);if(fortune.roll(state,c))persist();fortuneRender()},1000);
